119	  private getContextualDetails(): string {
120	    let details = '';
121	    // append optional [in directory]
122	    // note explanation is needed even if validation fails due to absolute path
123	    if (this.params.dir_path) {
124	      details += `[in ${this.params.dir_path}]`;
125	    } else {
126	      details += `[current working directory ${process.cwd()}]`;
127	    }
128	    // append optional (description), replacing any line breaks with spaces
129	    if (this.params.description) {
130	      details += ` (${this.params.description.replace(/\n/g, ' ')})`;
131	    }
132	    if (this.params.is_background) {
133	      details += ' [background]';
134	    }
135	    return details;
136	  }
