138	  getDescription(): string {
139	    const descStr = this.params.description?.trim();
140	    const commandStr = this.params.command;
141	    return Array.from(commandStr).length <= SHOW_NL_DESCRIPTION_THRESHOLD ||
142	      !descStr
143	      ? commandStr
144	      : descStr;
145	  }
